    sid = os.path.basename(os.path.dirname(path))
    raw = subprocess.check_output(['zstd','-dc',path])
    start=None
    for line in raw.splitlines():
        try: r=json.loads(line)
        except: continue
        if r.get('type')=='session': start=r.get('createdAt')
        t=r.get('time')
        if not t: continue
        day=datetime.datetime.fromtimestamp(t/1000).date().isoformat()
        typ=r.get('type')
        if typ in ('user/message','assistant/message'):
            by_day_msgs[day]+=1
            by_day_sessions[day].add(sid)
        if typ=='assistant/message':
            u=(r.get('data') or {}).get('usage') or {}
            by_day_tokens[day]+=int(u.get('totalTokens') or 0)
    if start:
        rows.append((datetime.datetime.fromtimestamp(start/1000).date().isoformat(),sid))
print('sessions',len(sessions))
for d in sorted(set(list(by_day_msgs)+[r[0] for r in rows])):
