    if typ=='session':
        created=datetime.datetime.fromtimestamp(r.get('createdAt')/1000).astimezone().isoformat(timespec='seconds')
        md.append(f'## Session start\n\n- created: {created}\n- cwd: `{r.get("cwd")}`\n- version: {r.get("version")}\n\n')
    elif typ=='system/message':
        body=text_of(d)
        md.append(f'## System message\n\n{fence(body)}\n{body}\n{fence(body)}\n\n')
    elif typ=='user/message':
